import { current } from '@reduxjs/toolkit';
import React from 'react';

const Profile = () => {
  return (
    <div>
      {!currentUser ? <span>You need to login</span>: (
                  <form >
                  <div className={styles.register__title}>Register</div>
                  <div className={styles['register__input-item']}>
                    <input
                      type="email"
                      placeholder='Email address'
                      name='email'
                      value={values.email}
                      autoComplete="off"
                      onChange={handleChange}
                      required
                    />
                  </div>
                  <div className={styles['register__input-item']}>
                    <input
                      type="password"
                      className={styles['password-input']}
                      placeholder='Password'
                      name='password'
                      value={values.password}
                      autoComplete="off"
                      onChange={handleChange}
                      required
                    />
                  </div>
                  <div className={styles['register__input-item']}>
                    <input
                      type="text"
                      placeholder='Username'
                      name='name'
                      value={values.name}
                      autoComplete="off"
                      onChange={handleChange}
                      required
                    />
                  </div>
                  <div className={styles['register__input-item']}>
                    <input
                      type="url"
                      placeholder='Avatar'
                      name='avatar'
                      value={values.avatart}
                      autoComplete="off"
                      onChange={handleChange}
                      required
                    />
                  </div>
                  <button onClick={() => toggleCurrentFormType('login')} className={styles['Have-button']}>I already have an account</button>
                  <button type='submit' onClick={handleSubmit} className={styles['register-button']}>Create an account</button>
                </form>
      )}
    </div>
  );
}

export default Profile;
